<td><select aria-label="Rule <?= $i+1 ?> account" name="rules[<?= $i ?>][account]"><?php foreach ($accounts as $a): ?><option value="<?= e($a['id']) ?>" <?= $rule['target_id']===$a['id'] ? 'selected' : '' ?>><?= e($a['name']) ?></option><?php endforeach; ?></select></td>
