<section class="card" id="budgets"><h2>Monthly budgets</h2><p class="muted">Use zero for categories you don’t want to limit.</p><form action="/settings/budgets" method="post" class="stack"><?= csrf_field() ?><?php foreach ($categories as $c): ?><label class="budget-label"><?= e($c['name']) ?><input name="budgets[<?= e($c['id']) ?>]" aria-label="<?= e($c['name']) ?> monthly budget in rupees" type="number" min="0" step="0.01" max="9999999999.99" value="<?= e($c['monthly_budget']) ?>" required></label><?php endforeach; ?><button>Save budgets</button></form><h3>Add a category</h3><form action="/settings/categories" method="post" class="form-grid"><?= csrf_field() ?><label>Name<input name="name" maxlength="100" required></label><label>Budget (Rs.)<input name="budget" type="number" min="0" max="9999999999.99" step="0.01" value="0" required></label><div class="full"><button class="secondary">Create category</button></div></form></section></div>
<div class="two-col"><section class="card"><h2>PIN lock</h2><p class="muted"><?= $pinSet ? 'Your workspace has a PIN. Enter it to make changes.' : 'Add an optional PIN for your workspace.' ?> A PIN locks the interface; it does not encrypt your database.</p><form method="post" action="/settings/pin" class="stack" hx-boost="false"><?= csrf_field() ?><?php if ($pinSet): ?><label>Current PIN<input type="password" name="current_pin" inputmode="numeric" autocomplete="current-password" required></label><?php endif; ?><label>New PIN<input type="password" name="pin" inputmode="numeric" pattern="[0-9]{4,12}" maxlength="12" autocomplete="new-password"></label><label>Confirm new PIN<input type="password" name="pin_confirm" inputmode="numeric" maxlength="12" autocomplete="new-password"></label><p class="footnote">4–12 digits. Leave both new fields empty to remove the lock.</p><button>Save PIN settings</button></form></section>
<section class="card"><h2>Backups & export</h2><p class="muted">A consistent daily snapshot is created automatically. The latest 14 daily backups are kept. Manual backups stay until you remove them.</p><div class="stack"><form method="post" action="/settings/backup"><?= csrf_field() ?><button class="secondary">Create local backup</button></form><form method="post" action="/settings/export" hx-boost="false"><?= csrf_field() ?><button>Export database</button></form></div><h3>Recent backups</h3><?php if (!$backups): ?><p class="muted">No backups yet.</p><?php else: ?><ul class="backup-list"><?php foreach (array_slice($backups,0,10) as $file): ?><li><a hx-boost="false" href="/settings/backup/<?= e(basename($file)) ?>"><?= e(basename($file)) ?></a><small><?= e(number_format(filesize($file)/1024,1)) ?> KB</small></li><?php endforeach; ?></ul><?php endif; ?><p class="footnote">Stored in your installation’s data/backups folder. Export a copy to another disk regularly.</p></section></div>
